  "ac.noBidsD2": { lv: "Solījumi parādīsies šeit uzreiz pēc pirmās likmes.", ru: "Ставки появятся здесь сразу после первой.", en: "Bids show up here right after your first one.", et: "Pakkumised ilmuvad siia kohe pärast esimest.", lt: "Pasiūlymai atsiras čia iškart po pirmojo." },
