  "ac.listEmptyD": { lv: "Nospied sirsniņu uz jebkura lota — tas parādīsies šeit.", ru: "Нажмите сердечко на любом лоте — он появится здесь.", en: "Tap the heart on any lot and it will show up here.", et: "Vajuta südamele mis tahes partiil — see ilmub siia.", lt: "Paspauskite širdelę ant bet kurio loto — jis atsiras čia." },
  "ac.noAlerts": { lv: "Brīdinājumu vēl nav", ru: "Уведомлений пока нет", en: "No alerts yet", et: "Teavitusi veel pole", lt: "Pranešimų dar nėra" },
  "ac.noAlertsD": { lv: "Nospied zvaniņu uz lota — brīdināsim par līdzīgiem.", ru: "Нажмите колокольчик на лоте — сообщим о похожих.", en: "Tap the bell on a lot and we will alert you about similar ones.", et: "Vajuta partii kellale — teavitame sarnastest.", lt: "Paspauskite varpelį ant loto — pranešime apie panašius." },
