  "sec.noBidsYetD": { lv: "Kad būsi solījis, šeit redzēsi aktīvos solījumus, pārsolīšanas brīdinājumus un uzvarētos lotus.", ru: "Как только сделаете ставку, здесь появятся активные ставки, уведомления о перебитых ставках и выигранные лоты.", en: "Once you bid, this is where your active bids, outbid alerts and won lots will appear.", et: "Kui oled pakkunud, näed siin aktiivseid pakkumisi, ületamise teateid ja võidetud partiisid.", lt: "Kai pasiūlysite, čia matysite aktyvius pasiūlymus, perviršijimo pranešimus ir laimėtus lotus." },
  "sec.findFirst": { lv: "Atrast pirmo lotu", ru: "Найти первый лот", en: "Find your first lot", et: "Leia esimene partii", lt: "Rasti pirmą lotą" },
  "sec.rightNow": { lv: "Notiek tieši tagad", ru: "Идёт прямо сейчас", en: "Happening right now", et: "Toimub just praegu", lt: "Vyksta dabar" },
  "sec.rightNowD": { lv: "Lotus izsauc pa vienam · solī pret zāli", ru: "Лоты объявляют по одному · торгуйтесь против зала", en: "Lots are called one by one · bid against the room", et: "Partiisid kuulutatakse ükshaaval · paku saali vastu", lt: "Lotai skelbiami po vieną · siūlykite prieš salę" },
