  "sec.allBrands": { lv: "Visi zīmoli", ru: "Все бренды", en: "All brands", et: "Kõik kaubamärgid", lt: "Visi prekės ženklai" },
  "sec.sameGoods": { lv: "Tā pati prece.", ru: "Тот же товар.", en: "The same item.", et: "Sama kaup.", lt: "Ta pati prekė." },
  "sec.marketPrice": { lv: "Cena, ko nosaka tirgus.", ru: "Цена, которую задаёт рынок.", en: "At a price the market sets.", et: "Hind, mille määrab turg.", lt: "Kaina, kurią nustato rinka." },
  "sec.whyLead": { lv: "Mēs pērkam noliktavu atlikumus un kolekcijas veselos apjomos. Tu maksā par preci, nevis par plauktu veikalā.", ru: "Мы выкупаем складские остатки и коллекции целыми объёмами. Вы платите за товар, а не за полку в магазине.", en: "We buy warehouse stock and collections in bulk. You pay for the item, not for shelf space in a shop.", et: "Ostame laojääke ja kollektsioone tervikuna. Maksad kauba, mitte poeriiuli eest.", lt: "Perkame sandėlio likučius ir kolekcijas visa apimtimi. Mokate už prekę, o ne už lentyną parduotuvėje." },
  "sec.endingToday": { lv: "Skatīt, kas beidzas šodien", ru: "Смотреть, что заканчивается сегодня", en: "See what ends today", et: "Vaata, mis lõpeb täna", lt: "Žiūrėti, kas baigiasi šiandien" },
  "sec.barShop": { lv: "Veikalā", ru: "В магазине", en: "In a shop", et: "Poes", lt: "Parduotuvėje" },
  "sec.barOther": { lv: "Citas izsoļu platformas", ru: "Другие аукционные площадки", en: "Other auction platforms", et: "Teised oksjoniplatvormid", lt: "Kitos aukcionų platformos" },
  "sec.barUs": { lv: "Izsoli.lv — pašreizējais solījums", ru: "Izsoli.lv — текущая ставка", en: "Izsoli.lv — current bid", et: "Izsoli.lv — praegune pakkumine", lt: "Izsoli.lv — dabartinis pasiūlymas" },
  "sec.barNote": { lv: "Vidējā uzvarējušā solījuma cena šajā kategorijā pēdējās 90 dienās. Cenas ar PVN.", ru: "Средняя цена победившей ставки в этой категории за последние 90 дней. Цены с НДС.", en: "Average winning bid in this category over the last 90 days. Prices include VAT.", et: "Keskmine võitnud pakkumine selles kategoorias viimase 90 päeva jooksul. Hinnad sisaldavad käibemaksu.", lt: "Vidutinė laimėjusio pasiūlymo kaina šioje kategorijoje per pastarąsias 90 dienų. Kainos su PVM." },
  "sec.step1": { lv: "Izvēlies lotu", ru: "Выберите лот", en: "Choose a lot", et: "Vali partii", lt: "Pasirinkite lotą" },
  "sec.step1D": { lv: "Reāli foto, godīgs stāvokļa apraksts pēc skalas A–D un ieteiktā cena salīdzinājumam.", ru: "Реальные фото, честное описание состояния по шкале A–D и розничная цена для сравнения.", en: "Real photos, an honest condition description on the A–D scale and a retail price for comparison.", et: "Päris fotod, aus seisukorra kirjeldus A–D skaalal ja soovituslik hind võrdluseks.", lt: "Tikros nuotraukos, sąžiningas būklės aprašymas pagal A–D skalę ir rekomenduojama kaina palyginimui." },
  "sec.step2": { lv: "Ievadi maksimumu", ru: "Задайте максимум", en: "Set your maximum", et: "Sisesta maksimum", lt: "Nurodykite maksimumą" },
  "sec.step2D": { lv: "Sistēma solī tavā vietā līdz norādītajai summai. Pārsolīšanas gadījumā saņem paziņojumu.", ru: "Система ставит за вас до указанной суммы. Если ставку перебьют, придёт уведомление.", en: "The system bids for you up to that amount. If you are outbid, you get a notification.", et: "Süsteem pakub sinu eest kuni selle summani. Ületamise korral saad teate.", lt: "Sistema siūlo už jus iki nurodytos sumos. Jei jus perviršys, gausite pranešimą." },
  "sec.step3": { lv: "Samaksā un saņem", ru: "Оплатите и получите", en: "Pay and receive", et: "Maksa ja saa kätte", lt: "Sumokėkite ir atsiimkite" },
  "sec.step3D": { lv: "Karte vai bankas saite. Izsūtām nākamajā darba dienā, pakomātā esi pēc 48 stundām.", ru: "Карта или банковская ссылка. Отправляем на следующий рабочий день, в пакомате — через 48 часов.", en: "Card or bank link. We ship the next working day; it is in the parcel machine within 48 hours.", et: "Kaart või pangalink. Saadame järgmisel tööpäeval, pakiautomaadis oled 48 tunni pärast.", lt: "Kortelė arba banko nuoroda. Išsiunčiame kitą darbo dieną, siuntų automate — po 48 valandų." },
  "sec.seoAria": { lv: "Par Izsoli.lv izsolēm", ru: "Об аукционах Izsoli.lv", en: "About Izsoli.lv auctions", et: "Izsoli.lv oksjonitest", lt: "Apie Izsoli.lv aukcionus" },
  "sec.faqIntro": { lv: "Solīšana, piegāde, atgriešana un stāvokļa skala — īsi un bez juridiskās miglas.", ru: "Ставки, доставка, возврат и шкала состояния — коротко и без юридического тумана.", en: "Bidding, delivery, returns and the condition scale — briefly and without legal fog.", et: "Pakkumine, tarne, tagastamine ja seisukorra skaala — lühidalt ja ilma juriidilise uduta.", lt: "Siūlymas, pristatymas, grąžinimas ir būklės skalė — trumpai ir be teisinio rūko." },
  "sec.allFaq": { lv: "Skatīt visus BUJ", ru: "Смотреть все вопросы", en: "See all FAQs", et: "Vaata kõiki KKK-sid", lt: "Žiūrėti visus klausimus" },
  "sec.noAnswer": { lv: "Neatradi atbildi?", ru: "Не нашли ответ?", en: "Did not find an answer?", et: "Ei leidnud vastust?", lt: "Neradote atsakymo?" },
  "sec.writeUs": { lv: "Raksti mums", ru: "Напишите нам", en: "Write to us", et: "Kirjuta meile", lt: "Parašykite mums" },
  "sec.replyIn": { lv: " — atbildam 1 darba dienas laikā.", ru: " — отвечаем в течение 1 рабочего дня.", en: " — we reply within 1 working day.", et: " — vastame 1 tööpäeva jooksul.", lt: " — atsakome per 1 darbo dieną." },
  "sec.seoH": { lv: "Online izsoles Latvijā — sāc solīt ar 1 EUR", ru: "Онлайн-аукционы в Латвии — начните торги с 1 EUR", en: "Online auctions in Latvia — start bidding at €1", et: "Online-oksjonid Lätis — alusta pakkumist 1 eurost", lt: "Internetiniai aukcionai Latvijoje — pradėkite siūlyti nuo 1 EUR" },
  "sec.seoP1a": { lv: "Izsoli.lv ir online izsoļu platforma Rīgā. Katrs lots sākas ar zemu sākumcenu, un gala cenu nosaka solītāji. Apskati", ru: "Izsoli.lv — площадка онлайн-аукционов в Риге. Каждый лот стартует с низкой начальной цены, а итоговую задают участники. Откройте", en: "Izsoli.lv is an online auction platform in Riga. Every lot starts at a low opening price and the bidders set the final one. Browse", et: "Izsoli.lv on online-oksjoniplatvorm Riias. Iga partii algab madala alghinnaga ja lõpphinna määravad pakkujad. Vaata", lt: "Izsoli.lv — internetinių aukcionų platforma Rygoje. Kiekvienas lotas prasideda nuo žemos pradinės kainos, o galutinę nustato dalyviai. Peržiūrėkite" },
  "sec.seoFullCat": { lv: "pilno katalogu", ru: "полный каталог", en: "the full catalogue", et: "kogu kataloogi", lt: "visą katalogą" },
