  "sec.seoWatches": { lv: "pulksteņiem un rotaslietām", ru: "часов и украшений", en: "watches and jewellery", et: "kelladest ja ehetest", lt: "laikrodžių ir papuošalų" },
  "sec.seoPopular": { lv: "Populārākās kategorijas:", ru: "Популярные категории:", en: "Most popular categories:", et: "Populaarseimad kategooriad:", lt: "Populiariausios kategorijos:" },
  "sec.seoCameras": { lv: "kameras un optika", ru: "камеры и оптика", en: "cameras and optics", et: "kaamerad ja optika", lt: "fotoaparatai ir optika" },
